/* Long illustrated stories, part 2: Aesop-style fables, Indian folk tales and four new stories (all traditional, retold in our words). */
(() => {
  'use strict';
  const LONG = window.KKM_LONG;

  // ================================================================ The Thirsty Crow
  LONG('crow', null, '🐦', [
    ['desert', '🐦 🥵', `It was a very hot summer day. The sun was burning, and a crow had been flying for a long time.`, `गर्मी का बहुत तपता दिन था। सूरज आग बरसा रहा था, और एक कौआ बहुत देर से उड़ रहा था।`],
    ['desert', '^🐦 😩', `“I am so thirsty,” said the crow. He looked everywhere for water, but the ponds and rivers were dry.`, `“मुझे बहुत प्यास लगी है,” कौए ने कहा। उसने हर जगह पानी ढूँढा, पर तालाब और नदियाँ सूखे थे।`],
    ['village', '🐦 😃 🏺', `At last, in a garden, he saw a pot. He flew down quickly. There was water inside!`, `आखिर में एक बगीचे में उसे एक मटका दिखा। वह झट से नीचे उतरा। अंदर पानी था!`],
    ['village', '🐦 😟 🏺', `But the water was right at the bottom. He pushed his beak in, but it could not reach. The pot was too heavy to tip over.`, `पर पानी बिल्कुल तली में था। उसने चोंच डाली, पर पहुँच नहीं पाई। मटका इतना भारी था कि गिराया भी नहीं जा सकता था।`],
    ['village', '🐦 💭 🪨', `The crow did not give up. He sat and thought. Then he saw a heap of small pebbles nearby. He had an idea!`, `कौए ने हार नहीं मानी। वह बैठकर सोचने लगा। तभी उसे पास में कंकड़ों का ढेर दिखा। उसे एक तरकीब सूझी!`],
    ['village', '🐦 🪨 🏺', `He picked up one pebble and dropped it in the pot. Plop! Then another. Plop! And another. Plop!`, `उसने एक कंकड़ उठाकर मटके में डाला। टप! फिर एक और। टप! और एक। टप!`],
    ['village', '🐦 💦 🏺', `With every pebble, the water rose a little higher… and higher… and higher!`, `हर कंकड़ के साथ पानी थोड़ा ऊपर आता… और ऊपर… और ऊपर!`],
    ['village', '🐦 😊 💧', `At last the water reached the top. The crow drank and drank until he was happy and cool. Then he flew away, cawing a happy song.`, `आखिरकार पानी ऊपर आ गया। कौए ने जी भरकर पानी पिया और तरोताज़ा हो गया। फिर वह खुशी से काँव-काँव करता उड़ गया।`],
  ], ['Where there is a will, there is a way. Think, and do not give up.', 'जहाँ चाह, वहाँ राह। सोचो, और हार मत मानो।'], [
    [['Why was the crow looking for water?', 'कौआ पानी क्यों ढूँढ रहा था?'], [['He was thirsty', 'उसे प्यास लगी थी'], ['He wanted a bath', 'उसे नहाना था'], ['He was cold', 'उसे ठंड लगी थी']], 0],
    [['What did he put in the pot?', 'उसने मटके में क्या डाला?'], [['Pebbles', 'कंकड़'], ['Leaves', 'पत्ते'], ['Bread', 'रोटी']], 0],
    [['What happened to the water?', 'पानी का क्या हुआ?'], [['It came up', 'ऊपर आ गया'], ['It went down', 'नीचे चला गया'], ['It turned red', 'लाल हो गया']], 0],
    [['What did the crow NOT do?', 'कौए ने क्या नहीं किया?'], [['Give up', 'हार मानना'], ['Think', 'सोचना'], ['Drink', 'पीना']], 0],
  ]);

  // ================================================================ The Lion and the Mouse
  LONG('lion-mouse', null, '🦁', [
    ['forest', '+🦁 😴', `A big lion was sleeping under a tree in the forest. He was snoring loudly: “Grrr… zzz… grrr… zzz.”`, `जंगल में एक बड़ा शेर पेड़ के नीचे सो रहा था। वह ज़ोर-ज़ोर से खर्राटे ले रहा था: “घर्र… ज़्ज़्ज़… घर्र…”`],
    ['forest', '🐭 😄 🦁', `A little mouse came out to play. Without looking, he ran right over the lion’s nose!`, `एक नन्हा चूहा खेलने निकला। बिना देखे वह सीधे शेर की नाक पर से दौड़ गया!`],
    ['forest', '🦁 😠 🐭', `The lion woke up and caught the mouse in his big paw. “How dare you wake me? I will eat you!”`, `शेर जाग गया और उसने चूहे को अपने बड़े पंजे में पकड़ लिया। “मुझे जगाने की हिम्मत? मैं तुम्हें खा जाऊँगा!”`],
    ['forest', '🐭 🙏 🦁', `“Please let me go, king!” cried the mouse. “I am so small. One day I may help you.”`, `“मुझे छोड़ दीजिए, महाराज!” चूहा रोया। “मैं बहुत छोटा हूँ। एक दिन मैं आपकी मदद कर सकता हूँ।”`],
    ['forest', '🦁 😂 🐭', `The lion laughed. “A tiny mouse help ME? That is funny! All right, go.” And he let the mouse go.`, `शेर हँस पड़ा। “एक नन्हा चूहा मेरी मदद करेगा? कितनी मज़ेदार बात! ठीक है, जाओ।” और उसने चूहे को छोड़ दिया।`],
    ['forest', '🧔 🕸️ 🦁', `A few days later, hunters came. They tied a strong net between the trees, and the lion walked right into it!`, `कुछ दिनों बाद शिकारी आए। उन्होंने पेड़ों के बीच मज़बूत जाल बाँधा, और शेर सीधे उसमें जा फँसा!`],
    ['forest', '🦁 😫 🕸️', `The lion pulled and roared, but the net held him tight. “ROAR! Help!” His roar shook the whole forest.`, `शेर ने खींचा और दहाड़ा, पर जाल ने उसे कसकर जकड़ लिया। “दहाड़! बचाओ!” उसकी दहाड़ से पूरा जंगल काँप उठा।`],
    ['forest', '🐭 👂 🦁', `The little mouse heard him. “That is my friend the lion!” He ran as fast as his tiny legs could go.`, `नन्हे चूहे ने सुना। “यह तो मेरे दोस्त शेर की आवाज़ है!” वह अपनी छोटी टाँगों से जितना तेज़ हो सका, दौड़ा।`],
    ['forest', '🐭 🕸️ 🦁', `Nibble, nibble, nibble! With his sharp little teeth, the mouse cut the ropes one by one. Soon there was a big hole.`, `कुतर, कुतर, कुतर! अपने छोटे तेज़ दाँतों से चूहे ने एक-एक रस्सी काट दी। जल्दी ही बड़ा छेद बन गया।`],
    ['forest', '🦁 😊 🐭', `The lion walked out, free! “Thank you, my friend,” he said. “I laughed at you, but you saved my life.”`, `शेर आज़ाद होकर बाहर आया! “धन्यवाद, मेरे दोस्त,” उसने कहा। “मैं तुम पर हँसा था, पर तुमने मेरी जान बचाई।”`],
  ], ['Never laugh at anyone for being small. Kindness comes back to you.', 'किसी को छोटा समझकर मत हँसो। भलाई लौटकर आती है।'], [
    [['How did the mouse wake the lion?', 'चूहे ने शेर को कैसे जगाया?'], [['He ran over his nose', 'उसकी नाक पर से दौड़ा'], ['He sang loudly', 'ज़ोर से गाया'], ['He pulled his tail', 'उसकी पूँछ खींची']], 0],
    [['Why did the lion laugh?', 'शेर क्यों हँसा?'], [['He thought a mouse could not help him', 'उसे लगा चूहा मदद नहीं कर सकता'], ['The mouse told a joke', 'चूहे ने चुटकुला सुनाया'], ['He was tickled', 'उसे गुदगुदी हुई']], 0],
    [['What trapped the lion?', 'शेर किसमें फँसा?'], [['A hunter’s net', 'शिकारी का जाल'], ['A cage', 'पिंजरा'], ['Mud', 'कीचड़']], 0],
    [['What did the lion learn?', 'शेर ने क्या सीखा?'], [['Small friends can help too', 'छोटे दोस्त भी मदद कर सकते हैं'], ['Mice are tasty', 'चूहे स्वादिष्ट हैं'], ['Never sleep', 'कभी मत सोओ']], 0],
  ]);

  // ================================================================ The Hare and the Tortoise
  LONG('hare', null, '🐇', [
    ['meadow', '🐇 😏 🐢', `A hare was always showing off. “I am the fastest animal in the forest! Look at you, tortoise – you are SO slow!”`, `एक खरगोश हमेशा शेखी बघारता। “मैं जंगल में सबसे तेज़ हूँ! और तुम्हें देखो, कछुए – तुम कितने धीमे हो!”`],
    ['meadow', '🐢 🙂 🐇', `The tortoise smiled calmly. “Slow, yes. But shall we have a race?” The hare laughed so much he fell down.`, `कछुआ शांति से मुस्कुराया। “धीमा तो हूँ। पर क्या हम दौड़ लगाएँ?” खरगोश इतना हँसा कि लोट-पोट हो गया।`],
    ['meadow', '🦊 🏁 🐇 🐢', `All the animals came to watch. The fox was the judge. “Ready, steady, GO!”`, `सारे जानवर देखने आए। लोमड़ी निर्णायक बनी। “तैयार, सावधान, दौड़ो!”`],
    ['road', '🐇 💨', `Whoosh! The hare shot off like an arrow. In a few moments he was far, far ahead.`, `सर्र! खरगोश तीर की तरह भागा। कुछ ही पलों में वह बहुत आगे निकल गया।`],
    ['road', '🐢 💪', `The tortoise walked slowly but steadily. Step, step, step. He never stopped.`, `कछुआ धीरे-धीरे, पर लगातार चलता रहा। कदम, कदम, कदम। वह कभी नहीं रुका।`],
    ['tree', '🐇 😴 🌳', `The hare looked back. The tortoise was nowhere to be seen. “I have lots of time. I’ll take a little nap,” he yawned.`, `खरगोश ने पीछे देखा। कछुआ कहीं दिख ही नहीं रहा था। “बहुत समय है। थोड़ी झपकी ले लूँ,” उसने जम्हाई ली।`],
    ['tree', '🐢 🐇 😴', `The tortoise walked past the sleeping hare – slowly, quietly, steadily.`, `कछुआ सोते हुए खरगोश के पास से निकल गया – धीरे, चुपचाप, लगातार।`],
    ['meadow', '🐢 🏁 🎉', `He walked on and on, and he crossed the finish line! The animals cheered, “The tortoise wins!”`, `वह चलता रहा, चलता रहा, और उसने अंतिम रेखा पार कर ली! जानवरों ने तालियाँ बजाईं, “कछुआ जीत गया!”`],
    ['meadow', '🐇 😳 🐢', `The cheering woke the hare. He ran very fast, but it was too late. He said, “I was proud and lazy. You were slow but you never gave up.”`, `तालियों से खरगोश जागा। वह बहुत तेज़ दौड़ा, पर देर हो चुकी थी। उसने कहा, “मैं घमंडी और आलसी था। तुम धीमे थे पर कभी नहीं रुके।”`],
  ], ['Slow and steady wins the race. Never be proud.', 'धीरे-धीरे पर लगातार चलने वाला जीतता है। घमंड मत करो।'], [
    [['Who was faster?', 'कौन तेज़ था?'], [['The hare', 'खरगोश'], ['The tortoise', 'कछुआ'], ['The fox', 'लोमड़ी']], 0],
    [['What did the hare do in the race?', 'खरगोश ने दौड़ में क्या किया?'], [['Took a nap', 'झपकी ली'], ['Ate carrots', 'गाजर खाई'], ['Helped the tortoise', 'कछुए की मदद की']], 0],
    [['Who won?', 'कौन जीता?'], [['The tortoise', 'कछुआ'], ['The hare', 'खरगोश'], ['Nobody', 'कोई नहीं']], 0],
    [['Why did the tortoise win?', 'कछुआ क्यों जीता?'], [['He never stopped', 'वह कभी नहीं रुका'], ['He ran fast', 'वह तेज़ भागा'], ['He cheated', 'उसने बेईमानी की']], 0],
  ]);

  // ================================================================ The Honest Woodcutter
  LONG('woodcutter', null, '🪓', [
    ['forest', '🧔 🪓 🌳', `A poor but honest woodcutter named Ramu cut wood in the forest every day and sold it to feed his family.`, `रामू नाम का एक गरीब पर ईमानदार लकड़हारा रोज़ जंगल में लकड़ी काटता और बेचकर परिवार का पेट भरता।`],
    ['river', '🧔 😱 ~🪓', `One day he was cutting a tree beside a river. His old iron axe slipped from his hands – SPLASH! – into the deep water.`, `एक दिन वह नदी किनारे पेड़ काट रहा था। उसकी पुरानी लोहे की कुल्हाड़ी हाथ से फिसली – छपाक! – गहरे पानी में।`],
    ['river', '🧔 😢', `He sat down and cried. “That was my only axe. How will I work now? How will my children eat?”`, `वह बैठकर रोने लगा। “वही मेरी इकलौती कुल्हाड़ी थी। अब मैं काम कैसे करूँगा? मेरे बच्चे क्या खाएँगे?”`],
    ['river', '🧚 ✨ 🧔', `Suddenly, a shining river goddess rose from the water. “Why are you crying?” she asked kindly. He told her everything.`, `अचानक पानी से एक चमकती जल देवी प्रकट हुई। “क्यों रो रहे हो?” उसने प्यार से पूछा। उसने सब बता दिया।`],
    ['river', '🧚 🥇 🧔', `She dived and came up with a GOLDEN axe. “Is this yours?” Ramu shook his head. “No, mother. Mine was not golden.”`, `उसने डुबकी लगाई और सोने की कुल्हाड़ी लेकर निकली। “क्या यह तुम्हारी है?” रामू ने सिर हिलाया। “नहीं माँ। मेरी सोने की नहीं थी।”`],
    ['river', '🧚 🥈 🧔', `She dived again and brought a SILVER axe. “This one?” “No, mother,” said Ramu. “Mine was not silver either.”`, `उसने फिर डुबकी लगाई और चाँदी की कुल्हाड़ी लाई। “यह वाली?” “नहीं माँ,” रामू बोला। “मेरी चाँदी की भी नहीं थी।”`],
    ['river', '🧚 🪓 🧔 😃', `The third time she brought an old iron axe. “Yes! That is mine!” cried Ramu happily.`, `तीसरी बार वह लोहे की पुरानी कुल्हाड़ी लाई। “हाँ! यही मेरी है!” रामू खुशी से चिल्लाया।`],
    ['river', '🧚 😊 🧔 🎁', `The goddess smiled. “You are truly honest. Keep all three axes as a gift!”`, `देवी मुस्कुराई। “तुम सच में ईमानदार हो। तीनों कुल्हाड़ियाँ इनाम में रख लो!”`],
    ['village', '🧔 👨‍👩‍👧 🏡', `Ramu went home and told his family. With the gift, they lived happily. But Ramu still worked hard every day.`, `रामू ने घर जाकर परिवार को बताया। उस इनाम से वे खुशी से रहे। पर रामू फिर भी रोज़ मेहनत करता रहा।`],
  ], ['Honesty is the best policy.', 'ईमानदारी सबसे अच्छी नीति है।'], [
    [['What fell into the river?', 'नदी में क्या गिरा?'], [['The axe', 'कुल्हाड़ी'], ['A shoe', 'जूता'], ['Bread', 'रोटी']], 0],
    [['Which axe did Ramu say was his?', 'रामू ने किस कुल्हाड़ी को अपना बताया?'], [['The iron one', 'लोहे वाली'], ['The golden one', 'सोने वाली'], ['The silver one', 'चाँदी वाली']], 0],
    [['Why did the goddess give him all three?', 'देवी ने उसे तीनों क्यों दीं?'], [['He was honest', 'वह ईमानदार था'], ['He was rich', 'वह अमीर था'], ['He cried loudly', 'वह ज़ोर से रोया']], 0],
  ], [2, 3]);

  // ================================================================ Unity is Strength (the bundle of sticks)
  LONG('sticks', null, '🥢', [
    ['village', '👴 👦 👦 👦', `An old farmer had four sons. They were strong, but they quarrelled all the time.`, `एक बूढ़े किसान के चार बेटे थे। वे ताकतवर थे, पर हर समय झगड़ते रहते।`],
    ['home', '👦 😠 👦', `“This is mine!” “No, mine!” The farmer was sad. “If they keep fighting, anyone can hurt them.”`, `“यह मेरा है!” “नहीं, मेरा!” किसान दुखी था। “अगर ये ऐसे ही लड़ते रहे, तो कोई भी इन्हें नुकसान पहुँचा देगा।”`],
    ['home', '👴 💡 🥢', `One day he called his sons. He gave them a bundle of sticks tied together. “Can you break this?”`, `एक दिन उसने बेटों को बुलाया। उसने उन्हें एक साथ बँधी लकड़ियों का गट्ठर दिया। “क्या तुम इसे तोड़ सकते हो?”`],
    ['home', '👦 💪 🥢', `The first son tried with all his strength. Then the second, the third and the fourth. Nobody could break the bundle.`, `पहले बेटे ने पूरी ताकत लगाई। फिर दूसरे, तीसरे और चौथे ने। कोई गट्ठर नहीं तोड़ पाया।`],
    ['home', '👴 ✂️ 🥢', `Then the farmer untied the bundle and gave each son one stick. “Now break it.”`, `फिर किसान ने गट्ठर खोला और हर बेटे को एक-एक लकड़ी दी। “अब तोड़ो।”`],
    ['home', '👦 💥 👦', `Snap! Snap! Snap! Snap! Each stick broke easily.`, `चटाक! चटाक! चटाक! चटाक! हर लकड़ी आसानी से टूट गई।`],
    ['home', '👴 😊 👦 👦', `“You are like these sticks,” said the farmer. “Alone, you are easy to break. Together, nobody can break you.”`, `“तुम भी इन लकड़ियों जैसे हो,” किसान बोला। “अकेले तुम्हें तोड़ना आसान है। साथ रहोगे, तो कोई नहीं तोड़ पाएगा।”`],
    ['field', '👦 🤝 👦 👦', `The sons understood. From that day they worked together, helped each other and never fought again.`, `बेटे समझ गए। उस दिन से वे मिलकर काम करते, एक-दूसरे की मदद करते और फिर कभी नहीं लड़े।`],
  ], ['Unity is strength. Together we are strong.', 'एकता में बल है। साथ रहकर हम मज़बूत हैं।'], [
    [['What did the sons always do?', 'बेटे हमेशा क्या करते?'], [['Quarrel', 'झगड़ते'], ['Sing', 'गाते'], ['Sleep', 'सोते']], 0],
    [['Could they break the bundle?', 'क्या वे गट्ठर तोड़ पाए?'], [['No', 'नहीं'], ['Yes, easily', 'हाँ, आसानी से'], ['Only the youngest', 'बस सबसे छोटा']], 0],
    [['What did the sticks teach?', 'लकड़ियों ने क्या सिखाया?'], [['Together we are strong', 'साथ रहकर हम मज़बूत हैं'], ['Sticks are fun', 'लकड़ियाँ मज़ेदार हैं'], ['Fight more', 'और लड़ो']], 0],
  ], [2, 3]);

  // ================================================================ The Ant and the Grasshopper
  LONG('ant', null, '🐜', [
    ['meadow', '🦗 🎻 🌼', `It was a sunny summer. A grasshopper spent every day singing, dancing and playing his fiddle.`, `गर्मियों के धूप वाले दिन थे। एक टिड्डा रोज़ गाता, नाचता और अपनी सारंगी बजाता।`],
    ['field', '🐜 🌾 🐜', `The ants were busy. Up and down they went all day, carrying grains of wheat to their home under the ground.`, `चींटियाँ व्यस्त थीं। वे दिन भर ऊपर-नीचे गेहूँ के दाने अपने ज़मीन के नीचे वाले घर में ले जातीं।`],
    ['field', '🦗 😄 🐜', `“Why work so hard? Come and play with me!” said the grasshopper.`, `“इतनी मेहनत क्यों? आओ मेरे साथ खेलो!” टिड्डे ने कहा।`],
    ['field', '🐜 🌾 🦗', `“We are saving food for winter,” said the ant. “You should save some too.” The grasshopper laughed. “Winter is far away!”`, `“हम सर्दियों के लिए खाना जमा कर रहे हैं,” चींटी ने कहा। “तुम भी कुछ जमा कर लो।” टिड्डा हँसा। “सर्दी तो बहुत दूर है!”`],
    ['snow', '🦗 🥶', `Then winter came. Snow covered the fields. There was no food anywhere. The grasshopper was cold and hungry.`, `फिर सर्दी आई। खेत बर्फ़ से ढक गए। कहीं खाना नहीं था। टिड्डा ठंडा और भूखा था।`],
    ['home', '🐜 🍲 🐜', `Under the ground, the ants were warm. They had plenty of food, because they had worked in the summer.`, `ज़मीन के नीचे चींटियाँ गरम थीं। उनके पास बहुत खाना था, क्योंकि उन्होंने गर्मियों में मेहनत की थी।`],
    ['snow', '🦗 🙏 🐜', `The grasshopper knocked on their door. “Please, can I have a little food? I am so hungry.”`, `टिड्डे ने उनका दरवाज़ा खटखटाया। “कृपया, क्या थोड़ा खाना मिलेगा? मुझे बहुत भूख लगी है।”`],
    ['home', '🐜 🍲 🦗 😊', `The kind ants shared their food. The grasshopper said, “Thank you. Next summer, I will play AND work.”`, `दयालु चींटियों ने अपना खाना बाँटा। टिड्डा बोला, “धन्यवाद। अगली गर्मी में मैं खेलूँगा भी और काम भी करूँगा।”`],
  ], ['Work today to be ready for tomorrow. And share with those in need.', 'आज मेहनत करो ताकि कल के लिए तैयार रहो। और ज़रूरतमंद से बाँटो।'], [
    [['What did the grasshopper do all summer?', 'टिड्डा गर्मियों में क्या करता था?'], [['Sang and played', 'गाता और खेलता'], ['Saved food', 'खाना जमा करता'], ['Built a house', 'घर बनाता']], 0],
    [['Why were the ants happy in winter?', 'सर्दी में चींटियाँ खुश क्यों थीं?'], [['They had saved food', 'उन्होंने खाना जमा किया था'], ['They had a heater', 'उनके पास हीटर था'], ['They slept', 'वे सो गईं']], 0],
    [['What did the ants do at the end?', 'आखिर में चींटियों ने क्या किया?'], [['Shared their food', 'खाना बाँटा'], ['Laughed', 'हँसीं'], ['Closed the door', 'दरवाज़ा बंद किया']], 0],
  ]);

  // ================================================================ The Boy Who Cried Wolf
  LONG('wolf', null, '🐺', [
    ['mountain', '👦 🐑 🐑', `A shepherd boy looked after the village sheep on a hill. Every day was the same, and he felt bored.`, `एक चरवाहा लड़का पहाड़ी पर गाँव की भेड़ें चराता था। हर दिन एक जैसा था, और वह ऊब जाता।`],
    ['mountain', '👦 😜 🐑', `He had a naughty idea. He shouted, “Wolf! Wolf! A wolf is eating the sheep!”`, `उसे एक शरारत सूझी। वह चिल्लाया, “भेड़िया! भेड़िया! भेड़िया भेड़ों को खा रहा है!”`],
    ['mountain', '👨‍🌾 👨 🏃', `The villagers dropped their work and ran up the hill with sticks. But there was no wolf. The boy laughed and laughed.`, `गाँव वाले अपना काम छोड़कर डंडे लेकर पहाड़ी पर दौड़े। पर वहाँ कोई भेड़िया नहीं था। लड़का हँसता रहा।`],
    ['mountain', '👨‍🌾 😠 👦', `“Do not lie like that,” said the villagers crossly, and went back down.`, `“ऐसे झूठ मत बोलो,” गाँव वालों ने गुस्से से कहा, और वापस लौट गए।`],
    ['mountain', '👦 😜 👨‍🌾', `A few days later he did it again. “Wolf! Wolf!” Again they ran up. Again there was no wolf.`, `कुछ दिनों बाद उसने फिर यही किया। “भेड़िया! भेड़िया!” वे फिर दौड़े। फिर कोई भेड़िया नहीं था।`],
    ['mountain', '🐺 😈 🐑', `Then one evening, a real wolf came out of the trees! It crept towards the sheep.`, `फिर एक शाम पेड़ों से सचमुच एक भेड़िया निकल आया! वह भेड़ों की ओर बढ़ा।`],
    ['mountain', '👦 😱 🐺', `“WOLF! WOLF! Please help! This time it is true!” the boy screamed.`, `“भेड़िया! भेड़िया! कृपया बचाओ! इस बार सच है!” लड़का चीखा।`],
    ['village', '👨‍🌾 🤷 👨', `In the village, people heard him but shook their heads. “He is lying again.” Nobody came.`, `गाँव में लोगों ने सुना पर सिर हिला दिया। “वह फिर झूठ बोल रहा है।” कोई नहीं आया।`],
    ['mountain', '👦 😢 🐑', `The wolf chased the sheep away into the forest. The boy cried. “Nobody believed me because I lied before.” He never lied again.`, `भेड़िया भेड़ों को जंगल में भगा ले गया। लड़का रोया। “किसी ने मेरी बात नहीं मानी क्योंकि मैंने पहले झूठ बोला था।” उसने फिर कभी झूठ नहीं बोला।`],
  ], ['Nobody believes a liar, even when he tells the truth.', 'झूठे की बात पर कोई विश्वास नहीं करता, सच बोलने पर भी नहीं।'], [
    [['What did the boy shout as a joke?', 'लड़का मज़ाक में क्या चिल्लाया?'], [['Wolf! Wolf!', 'भेड़िया! भेड़िया!'], ['Fire! Fire!', 'आग! आग!'], ['Rain! Rain!', 'बारिश! बारिश!']], 0],
    [['Why did nobody come the last time?', 'आखिरी बार कोई क्यों नहीं आया?'], [['They thought he was lying', 'उन्हें लगा वह झूठ बोल रहा है'], ['They were asleep', 'वे सो रहे थे'], ['They were scared', 'वे डरे हुए थे']], 0],
    [['What is the lesson?', 'सीख क्या है?'], [['Always tell the truth', 'हमेशा सच बोलो'], ['Wolves are kind', 'भेड़िये दयालु हैं'], ['Sheep can fly', 'भेड़ें उड़ सकती हैं']], 0],
  ]);

  // ================================================================ The Fox and the Grapes
  LONG('grapes', null, '🦊', [
    ['forest', '🦊 😋', `A hungry fox was walking through the forest, looking for something to eat.`, `एक भूखी लोमड़ी कुछ खाने की तलाश में जंगल में घूम रही थी।`],
    ['tree', '🦊 😍 @🍇', `She saw a bunch of juicy purple grapes hanging high on a vine. “Yum! Those look so sweet!”`, `उसे बेल पर ऊँचा लटका रसीले बैंगनी अंगूरों का गुच्छा दिखा। “वाह! कितने मीठे लगते हैं!”`],
    ['tree', '🦊 ⬆️ @🍇', `She jumped as high as she could. She missed! She jumped again. She missed again.`, `वह जितना ऊँचा हो सका, कूदी। चूक गई! फिर कूदी। फिर चूक गई।`],
    ['tree', '🦊 😫 @🍇', `She ran and jumped, again and again, until she was very tired. The grapes were too high.`, `वह दौड़-दौड़कर बार-बार कूदी, जब तक कि बहुत थक नहीं गई। अंगूर बहुत ऊँचे थे।`],
    ['forest', '🦊 😒', `At last she walked away with her nose in the air. “Hmph! Those grapes are sour anyway. I did not want them.”`, `आखिर में वह नाक ऊँची करके चल दी। “हुँह! वैसे भी अंगूर खट्टे हैं। मुझे चाहिए ही नहीं थे।”`],
    ['tree', '🐦 😄 @🍇', `A bird on the branch laughed. “They are sweet! She only says sour because she could not reach them.”`, `डाल पर बैठी चिड़िया हँसी। “अंगूर तो मीठे हैं! उसे मिले नहीं, इसलिए खट्टे बता रही है।”`],
  ], ['Do not pretend you did not want something just because you could not get it. Try another way!', 'जो न मिले, उसे बुरा मत बताओ। कोई और तरीका सोचो!'], [
    [['What did the fox want?', 'लोमड़ी क्या चाहती थी?'], [['Grapes', 'अंगूर'], ['A fish', 'मछली'], ['Water', 'पानी']], 0],
    [['Why did she say the grapes were sour?', 'उसने अंगूर खट्टे क्यों बताए?'], [['She could not reach them', 'वह उन तक पहुँच नहीं पाई'], ['She tasted them', 'उसने चखे थे'], ['A bird told her', 'चिड़िया ने बताया']], 0],
    [['What could she have done instead?', 'वह इसकी जगह क्या कर सकती थी?'], [['Tried another way, like climbing', 'कोई और तरीका, जैसे चढ़ना'], ['Cried', 'रोना'], ['Gone to sleep', 'सो जाना']], 0],
  ]);

  // ================================================================ The Dog and His Reflection
  LONG('dog', null, '🐕', [
    ['village', '🐕 🦴 😋', `A dog found a big, juicy bone near the market. “This is all mine!” he thought happily.`, `एक कुत्ते को बाज़ार के पास एक बड़ी, स्वादिष्ट हड्डी मिली। “यह पूरी मेरी है!” उसने खुशी से सोचा।`],
    ['river', '🐕 🦴 🌉', `He held it in his mouth and ran home. On the way, he crossed a little bridge over a stream.`, `वह उसे मुँह में दबाकर घर भागा। रास्ते में वह एक नाले पर बने छोटे पुल से गुज़रा।`],
    ['river', '🐕 😮 ~🐕', `He looked down into the water. There he saw another dog with another bone – an even bigger one!`, `उसने नीचे पानी में देखा। वहाँ उसे एक और कुत्ता, एक और हड्डी के साथ दिखा – उससे भी बड़ी!`],
    ['river', '🐕 😈 ~🦴', `“I want that bone too!” thought the greedy dog. He opened his mouth to bark: “WOOF!”`, `“मुझे वह हड्डी भी चाहिए!” लालची कुत्ते ने सोचा। उसने भौंकने के लिए मुँह खोला: “भौं!”`],
    ['river', '🐕 😱 💦', `Splash! His own bone fell into the water and sank to the bottom. The other dog was only his reflection!`, `छपाक! उसकी अपनी हड्डी पानी में गिरकर डूब गई। दूसरा कुत्ता तो बस उसकी परछाईं था!`],
    ['village', '🐕 😔', `He walked home with nothing. “I was greedy, and I lost what I had.”`, `वह खाली मुँह घर लौटा। “मैंने लालच किया, और जो था वह भी खो दिया।”`],
  ], ['Greed can make you lose what you already have. Be happy with what you have.', 'लालच से जो पास है वह भी चला जाता है। जो है उसमें खुश रहो।'], [
    [['What did the dog see in the water?', 'कुत्ते ने पानी में क्या देखा?'], [['His own reflection', 'अपनी परछाईं'], ['A fish', 'मछली'], ['A cat', 'बिल्ली']], 0],
    [['Why did he lose his bone?', 'उसकी हड्डी क्यों गई?'], [['He opened his mouth to bark', 'उसने भौंकने को मुँह खोला'], ['A bird took it', 'चिड़िया ले गई'], ['He gave it away', 'उसने दे दी']], 0],
    [['What is the lesson?', 'सीख क्या है?'], [['Don’t be greedy', 'लालच मत करो'], ['Bark more', 'और भौंको'], ['Never cross bridges', 'पुल कभी पार मत करो']], 0],
  ]);

  // ================================================================ The Ant and the Dove
  LONG('antdove', null, '🕊️', [
    ['river', '🐜 🥵', `On a hot day, a little ant went to the river to drink water.`, `एक गर्म दिन एक नन्ही चींटी पानी पीने नदी पर गई।`],
    ['river', '~🐜 😱 💦', `A wave came and swept her into the river! “Help! Help! I can’t swim!” she cried.`, `एक लहर आई और उसे नदी में बहा ले गई! “बचाओ! बचाओ! मुझे तैरना नहीं आता!” वह चिल्लाई।`],
    ['tree', '@🕊️ 🍃 🐜', `A dove sitting on a tree saw her. Quickly, she plucked a leaf and dropped it near the ant.`, `पेड़ पर बैठे एक कबूतर ने उसे देखा। उसने झट से एक पत्ता तोड़ा और चींटी के पास गिरा दिया।`],
    ['river', '~🐜 🍃 😊', `The ant climbed onto the leaf. It floated like a little boat to the bank. She was safe! “Thank you, dove!”`, `चींटी पत्ते पर चढ़ गई। वह छोटी नाव की तरह किनारे तक तैर गया। वह बच गई! “धन्यवाद, कबूतर!”`],
    ['forest', '🧔 🏹 @🕊️', `A few days later, a hunter came to the forest. He saw the dove and pulled back his bow to shoot her.`, `कुछ दिनों बाद जंगल में एक शिकारी आया। उसने कबूतर को देखा और उस पर निशाना साधा।`],
    ['forest', '🐜 💡 🧔', `The ant saw him. “My friend is in danger!” She ran and bit the hunter hard on his foot.`, `चींटी ने उसे देख लिया। “मेरे दोस्त को खतरा है!” वह दौड़ी और शिकारी के पैर में ज़ोर से काट लिया।`],
    ['forest', '🧔 😖 ^🕊️', `“Ouch!” The hunter jumped and his arrow missed. The dove heard the noise and flew away to safety.`, `“आह!” शिकारी उछला और उसका तीर चूक गया। आवाज़ सुनकर कबूतर उड़कर सुरक्षित जगह चला गया।`],
    ['tree', '🕊️ 😊 🐜', `Later, the dove came to thank the ant. “You saved me, and I saved you. That is what friends do!”`, `बाद में कबूतर चींटी को धन्यवाद देने आया। “तुमने मुझे बचाया, मैंने तुम्हें। दोस्त यही करते हैं!”`],
  ], ['Help others, and they will help you too. A good deed is never wasted.', 'दूसरों की मदद करो, वे भी तुम्हारी मदद करेंगे। भलाई कभी बेकार नहीं जाती।'], [
    [['How did the dove save the ant?', 'कबूतर ने चींटी को कैसे बचाया?'], [['Dropped a leaf', 'पत्ता गिराया'], ['Carried her', 'उसे उठा लिया'], ['Called a fish', 'मछली को बुलाया']], 0],
    [['How did the ant save the dove?', 'चींटी ने कबूतर को कैसे बचाया?'], [['Bit the hunter', 'शिकारी को काटा'], ['Shouted', 'चिल्लाई'], ['Hid the arrows', 'तीर छिपाए']], 0],
    [['What is the lesson?', 'सीख क्या है?'], [['A good deed comes back', 'भलाई लौटकर आती है'], ['Ants can fly', 'चींटियाँ उड़ सकती हैं'], ['Rivers are bad', 'नदियाँ बुरी हैं']], 0],
  ]);

  // ================================================================ The Golden Touch
  LONG('midas', null, '👑', [
    ['palace', '🤴 💰 🪙', `King Midas was very rich, but he loved gold more than anything. He counted his gold coins every day.`, `राजा मिडास बहुत अमीर था, पर उसे सोना सबसे ज़्यादा प्यारा था। वह रोज़ अपने सोने के सिक्के गिनता।`],
    ['palace', '🤴 🧚 ✨', `One day a magical fairy said, “You may have one wish.” Midas said, “I wish that everything I touch turns to gold!”`, `एक दिन एक जादुई परी ने कहा, “तुम एक वरदान माँग सकते हो।” मिडास बोला, “मैं जो भी छुऊँ, वह सोना बन जाए!”`],
    ['garden', '🤴 😃 🌹', `Next morning he touched a rose. It turned to gold! He touched a chair – gold! A tree – gold! “I am the happiest king!” he laughed.`, `अगली सुबह उसने एक गुलाब छुआ। वह सोना बन गया! कुर्सी छुई – सोना! पेड़ – सोना! “मैं सबसे खुश राजा हूँ!” वह हँसा।`],
    ['palace', '🤴 😟 🍎', `At lunch, he picked up an apple. It became hard gold. He tried to drink water – the water turned to gold too! He could not eat or drink.`, `दोपहर के खाने में उसने सेब उठाया। वह कड़ा सोना बन गया। उसने पानी पीना चाहा – पानी भी सोना बन गया! वह न खा सका, न पी सका।`],
    ['palace', '👧 🤗 🤴', `His little daughter ran to hug him. “Papa!” The moment he touched her, she turned into a golden statue!`, `उसकी नन्ही बेटी उसे गले लगाने दौड़ी। “पापा!” जैसे ही उसने उसे छुआ, वह सोने की मूर्ति बन गई!`],
    ['palace', '🤴 😭', `Midas cried bitterly. “What have I done? Gold cannot give me food, or water, or love!”`, `मिडास फूट-फूटकर रोया। “यह मैंने क्या कर दिया? सोना मुझे खाना, पानी या प्यार नहीं दे सकता!”`],
    ['river', '🤴 🙏 🧚', `He begged the fairy, “Please take back my wish!” She said, “Wash your hands in the river, and pour its water on what you touched.”`, `उसने परी से विनती की, “मेरा वरदान वापस ले लो!” वह बोली, “नदी में हाथ धोओ, और उसका पानी उन चीज़ों पर डालो जिन्हें छुआ था।”`],
    ['palace', '👧 😊 🤴', `He did. The rose turned red again, the apple became juicy, and his daughter laughed and hugged him!`, `उसने वैसा ही किया। गुलाब फिर लाल हो गया, सेब रसीला, और उसकी बेटी हँसकर उससे लिपट गई!`],
    ['garden', '🤴 💛 👧', `From that day, Midas knew what was truly precious: family, love and kindness – not gold.`, `उस दिन से मिडास जान गया कि असली खज़ाना क्या है: परिवार, प्यार और दया – सोना नहीं।`],
  ], ['Greed brings sadness. Love and family are worth more than gold.', 'लालच दुख लाता है। प्यार और परिवार सोने से कहीं ज़्यादा कीमती हैं।'], [
    [['What did Midas wish for?', 'मिडास ने क्या माँगा?'], [['Everything he touched turns to gold', 'जो छुए वह सोना बने'], ['A big cake', 'बड़ा केक'], ['To fly', 'उड़ना']], 0],
    [['Why did the wish become a problem?', 'वरदान मुसीबत क्यों बना?'], [['He could not eat or hug', 'वह न खा सका, न गले लगा सका'], ['Gold was too shiny', 'सोना बहुत चमकीला था'], ['He lost his crown', 'उसका मुकुट खो गया']], 0],
    [['What is truly precious?', 'असली खज़ाना क्या है?'], [['Love and family', 'प्यार और परिवार'], ['Gold coins', 'सोने के सिक्के'], ['Golden apples', 'सोने के सेब']], 0],
  ], [2, 3]);

  // ================================================================ Shravan Kumar
  LONG('shravan', null, '🙏', [
    ['village', '👦 👴 👵', `Long ago lived a boy named Shravan Kumar. His mother and father were old and could not see.`, `बहुत पहले श्रवण कुमार नाम का एक लड़का रहता था। उसके माता-पिता बूढ़े थे और देख नहीं सकते थे।`],
    ['home', '👦 🍲 👵', `Shravan loved them very much. He cooked for them, helped them walk and told them about everything around them.`, `श्रवण उनसे बहुत प्यार करता था। वह उनके लिए खाना बनाता, उन्हें चलने में मदद करता और आसपास की हर बात बताता।`],
    ['home', '👴 💭 👵', `One day his parents said, “Son, we wish to visit the holy places before we grow older.”`, `एक दिन माता-पिता ने कहा, “बेटा, हम और बूढ़े होने से पहले तीर्थ यात्रा करना चाहते हैं।”`],
    ['village', '👦 🧺 💡', `They had no money for a cart. So Shravan made a kaavad – two baskets tied to a strong bamboo pole.`, `उनके पास गाड़ी के पैसे नहीं थे। तो श्रवण ने एक काँवड़ बनाई – मज़बूत बाँस के डंडे से बँधी दो टोकरियाँ।`],
    ['road', '👦 🧺 👴 👵', `He put his mother in one basket and his father in the other, lifted the pole on his shoulders, and set off.`, `उसने माँ को एक टोकरी में, पिता को दूसरी में बिठाया, डंडा कंधे पर उठाया और चल पड़ा।`],
    ['mountain', '👦 💪 🧺', `He walked for many days, over hills and through forests, in hot sun and heavy rain. He never complained.`, `वह कई दिन चला, पहाड़ियों पर, जंगलों से, तेज़ धूप और भारी बारिश में। उसने कभी शिकायत नहीं की।`],
    ['river', '👦 🙏 🛕', `At every holy place, he described the temples and rivers to his parents, so they could see them in their minds.`, `हर तीर्थ पर वह माता-पिता को मंदिरों और नदियों का वर्णन करता, ताकि वे उन्हें मन की आँखों से देख सकें।`],
    ['forest', '👴 😊 👵 👦', `His parents blessed him with all their hearts. “You are the best son in the world.”`, `माता-पिता ने उसे दिल से आशीर्वाद दिया। “तुम दुनिया के सबसे अच्छे बेटे हो।”`],
    ['village', '👦 💛 👴', `Even today, when someone takes loving care of their parents, people say, “He is like Shravan Kumar.”`, `आज भी जब कोई अपने माता-पिता की प्यार से सेवा करता है, तो लोग कहते हैं, “वह श्रवण कुमार जैसा है।”`],
  ], ['Love, respect and care for your parents and elders.', 'अपने माता-पिता और बड़ों से प्यार करो, उनका आदर और सेवा करो।'], [
    [['What did Shravan make to carry his parents?', 'श्रवण ने माता-पिता को ले जाने के लिए क्या बनाया?'], [['A kaavad with two baskets', 'दो टोकरियों वाली काँवड़'], ['A car', 'गाड़ी'], ['A boat', 'नाव']], 0],
    [['Where did his parents want to go?', 'माता-पिता कहाँ जाना चाहते थे?'], [['To holy places', 'तीर्थ यात्रा पर'], ['To the market', 'बाज़ार'], ['To school', 'स्कूल']], 0],
    [['How can you be like Shravan?', 'तुम श्रवण जैसे कैसे बन सकते हो?'], [['Help and care for your parents', 'माता-पिता की मदद और सेवा करके'], ['Carry baskets', 'टोकरियाँ उठाकर'], ['Walk a lot', 'बहुत चलकर']], 0],
  ]);

  // ================================================================ Tenali Raman and the Thieves
  LONG('tenali', null, '🧔', [
    ['village', '🧔 🏡 🌳', `Tenali Raman was the cleverest man in King Krishnadevaraya’s court. He lived in a house with a big garden and a well.`, `तेनाली रामन राजा कृष्णदेवराय के दरबार के सबसे चतुर व्यक्ति थे। उनका घर बड़े बगीचे और कुएँ वाला था।`],
    ['night', '🧔 👀 🦹 🦹', `One night, he saw two thieves hiding behind the bushes, watching his house.`, `एक रात उन्होंने देखा कि दो चोर झाड़ियों के पीछे छिपकर उनके घर पर नज़र रखे हुए हैं।`],
    ['night', '🧔 💡 👩', `Tenali smiled and said loudly to his wife, “Thieves are about! Let us hide our gold and jewels in the box and drop it in the well.”`, `तेनाली मुस्कुराए और पत्नी से ज़ोर से बोले, “आजकल चोर घूम रहे हैं! चलो, सोना-गहने संदूक में भरकर कुएँ में डाल दें।”`],
    ['well', '🧔 📦 🪨', `Then, quietly, he filled the box with heavy stones! With a big splash, he dropped it into the well and went to sleep.`, `फिर चुपचाप उन्होंने संदूक में भारी पत्थर भर दिए! ज़ोर की छपाक के साथ उसे कुएँ में डालकर सोने चले गए।`],
    ['well', '🦹 🪣 🦹', `The thieves rushed to the well. “The treasure is ours!” They started pulling up bucket after bucket of water.`, `चोर कुएँ की ओर दौड़े। “खज़ाना हमारा!” वे बाल्टी पर बाल्टी पानी खींचने लगे।`],
    ['garden', '🦹 💦 🌱', `All night they pulled water and threw it on the ground. Without knowing, they were watering Tenali’s whole garden!`, `रात भर वे पानी खींचकर ज़मीन पर फेंकते रहे। बिना जाने वे तेनाली का पूरा बगीचा सींच रहे थे!`],
    ['well', '🦹 😩 📦', `At dawn they finally pulled up the box and opened it. Stones! Only stones!`, `सुबह होते-होते आखिर उन्होंने संदूक निकाला और खोला। पत्थर! बस पत्थर!`],
    ['garden', '🧔 😄 🦹', `Tenali came out and said, “Thank you for watering my garden! Now, shall we visit the king’s guards?” The thieves ran away and never came back.`, `तेनाली बाहर आए और बोले, “मेरा बगीचा सींचने के लिए धन्यवाद! अब राजा के सिपाहियों के पास चलें?” चोर भाग गए और फिर कभी नहीं लौटे।`],
  ], ['A calm, clever mind can solve any problem.', 'शांत और चतुर दिमाग हर समस्या सुलझा सकता है।'], [
    [['What did Tenali really put in the box?', 'तेनाली ने संदूक में असल में क्या डाला?'], [['Stones', 'पत्थर'], ['Gold', 'सोना'], ['Food', 'खाना']], 0],
    [['What did the thieves do all night?', 'चोरों ने रात भर क्या किया?'], [['Pulled water from the well', 'कुएँ से पानी खींचा'], ['Slept', 'सोए'], ['Sang songs', 'गाने गाए']], 0],
    [['How did this help Tenali?', 'इससे तेनाली को क्या फ़ायदा हुआ?'], [['His garden got watered', 'बगीचा सिंच गया'], ['He got gold', 'सोना मिला'], ['He got a horse', 'घोड़ा मिला']], 0],
  ]);

  // ================================================================ Birbal Counts the Crows
  LONG('crows', null, '🐦', [
    ['court', '🤴 😄 🧔', `Emperor Akbar loved to ask Birbal tricky questions. One sunny morning they were walking in the palace garden.`, `बादशाह अकबर को बीरबल से मुश्किल सवाल पूछना अच्छा लगता था। एक धूप वाली सुबह वे महल के बगीचे में टहल रहे थे।`],
    ['garden', '🤴 ^🐦 ^🐦', `Akbar saw many crows on the trees. He smiled. “Birbal, tell me – how many crows are there in our city?”`, `अकबर ने पेड़ों पर बहुत से कौए देखे। वे मुस्कुराए। “बीरबल, बताओ – हमारे शहर में कितने कौए हैं?”`],
    ['garden', '🧔 💭 🐦', `The courtiers whispered, “Nobody can count all the crows!” Birbal thought for a moment.`, `दरबारी फुसफुसाए, “सारे कौए कोई नहीं गिन सकता!” बीरबल ने एक पल सोचा।`],
    ['garden', '🧔 😊 🤴', `“There are exactly ninety-five thousand, four hundred and sixty-three crows, Your Majesty,” said Birbal.`, `“ठीक पचानवे हज़ार, चार सौ तिरसठ कौए हैं, जहाँपनाह,” बीरबल ने कहा।`],
    ['garden', '🤴 🧐 🧔', `“How can you be sure?” asked Akbar. “What if there are more, or fewer?”`, `“तुम्हें कैसे पक्का पता?” अकबर ने पूछा। “अगर ज़्यादा या कम हुए तो?”`],
    ['garden', '🧔 💡 🐦', `“If there are more,” said Birbal, “their relatives have come to visit. If there are fewer, some have gone to visit their relatives!”`, `“अगर ज़्यादा हुए,” बीरबल बोले, “तो उनके रिश्तेदार मिलने आए होंगे। अगर कम हुए, तो कुछ अपने रिश्तेदारों से मिलने गए होंगे!”`],
    ['court', '🤴 😂 🧔', `Akbar laughed and laughed. “Birbal, nobody can beat your wit!” He gave Birbal a gift.`, `अकबर हँसते रहे। “बीरबल, तुम्हारी हाज़िरजवाबी का कोई जवाब नहीं!” उन्होंने बीरबल को इनाम दिया।`],
  ], ['A quick, cheerful mind can answer even a tricky question.', 'तेज़ और खुशमिज़ाज दिमाग मुश्किल सवाल का भी जवाब ढूँढ लेता है।'], [
    [['What did Akbar ask Birbal?', 'अकबर ने बीरबल से क्या पूछा?'], [['How many crows are in the city', 'शहर में कितने कौए हैं'], ['How many stars are in the sky', 'आसमान में कितने तारे'], ['How old he was', 'उसकी उम्र']], 0],
    [['If there are more crows, what did Birbal say?', 'कौए ज़्यादा हुए तो बीरबल ने क्या कहा?'], [['Relatives came to visit', 'रिश्तेदार मिलने आए'], ['They were born today', 'आज पैदा हुए'], ['The king miscounted', 'राजा ने गलत गिना']], 0],
    [['What helped Birbal?', 'बीरबल के क्या काम आया?'], [['His quick wit', 'उसकी हाज़िरजवाबी'], ['A big book', 'मोटी किताब'], ['A ladder', 'सीढ़ी']], 0],
  ]);

  // ================================================================ The Elephant and the Tailor
  LONG('tailor', null, '🐘', [
    ['village', '🐘 🧔 🛕', `In a village lived a gentle elephant. Every day his keeper took him to the river for a bath.`, `एक गाँव में एक सीधा-सादा हाथी रहता था। रोज़ उसका महावत उसे नदी पर नहलाने ले जाता।`],
    ['market', '🐘 🧵 👨', `On the way was a tailor’s shop. The kind tailor always gave the elephant a banana. The elephant would wave his trunk to say thank you.`, `रास्ते में एक दर्ज़ी की दुकान थी। दयालु दर्ज़ी हमेशा हाथी को एक केला देता। हाथी सूँड़ हिलाकर धन्यवाद कहता।`],
    ['market', '🐘 🍌 😊', `They became good friends. The elephant looked forward to seeing the tailor every day.`, `वे अच्छे दोस्त बन गए। हाथी रोज़ दर्ज़ी से मिलने का इंतज़ार करता।`],
    ['market', '👦 😜 🪡', `One day the tailor went out. His naughty son sat in the shop. When the elephant put in his trunk, the boy pricked it with a needle!`, `एक दिन दर्ज़ी बाहर गया। दुकान पर उसका शरारती बेटा बैठा था। जब हाथी ने सूँड़ अंदर डाली, लड़के ने उसमें सुई चुभो दी!`],
    ['market', '🐘 😖 👦', `“Ouch!” The elephant pulled his trunk back. He was hurt and sad. He walked quietly to the river.`, `“आह!” हाथी ने सूँड़ पीछे खींच ली। उसे चोट लगी और वह दुखी हुआ। वह चुपचाप नदी की ओर चला गया।`],
    ['river', '🐘 💧 💭', `After his bath, he filled his trunk with muddy water from the river.`, `नहाने के बाद उसने नदी का कीचड़ वाला पानी अपनी सूँड़ में भर लिया।`],
    ['market', '🐘 💦 👦', `At the shop, he sprayed it all over the boy and the new clothes! Splash!`, `दुकान पर पहुँचकर उसने वह सारा पानी लड़के और नए कपड़ों पर उछाल दिया! छपाक!`],
    ['market', '🧔 😟 👦', `The tailor came back and heard what happened. “Son, the elephant was our friend. You hurt him, so he got upset.”`, `दर्ज़ी लौटा और सारी बात सुनी। “बेटा, हाथी हमारा दोस्त था। तुमने उसे चोट पहुँचाई, इसलिए वह नाराज़ हुआ।”`],
    ['market', '👦 🍌 🐘 😊', `The next day, the boy said sorry and gave the elephant a banana. The elephant waved his trunk. They were friends again.`, `अगले दिन लड़के ने माफ़ी माँगी और हाथी को केला दिया। हाथी ने सूँड़ हिलाई। वे फिर दोस्त बन गए।`],
  ], ['Be kind to animals. Treat others the way you want to be treated.', 'जानवरों से प्यार करो। दूसरों से वैसा ही व्यवहार करो जैसा तुम अपने लिए चाहते हो।'], [
    [['What did the tailor give the elephant?', 'दर्ज़ी हाथी को क्या देता था?'], [['A banana', 'केला'], ['A shirt', 'कमीज़'], ['Water', 'पानी']], 0],
    [['What did the naughty boy do?', 'शरारती लड़के ने क्या किया?'], [['Pricked the trunk with a needle', 'सूँड़ में सुई चुभोई'], ['Gave a sweet', 'मिठाई दी'], ['Sang a song', 'गाना गाया']], 0],
    [['How did the story end?', 'कहानी कैसे खत्म हुई?'], [['The boy said sorry and they became friends', 'लड़के ने माफ़ी माँगी और दोस्ती हो गई'], ['The elephant ran away', 'हाथी भाग गया'], ['The shop closed', 'दुकान बंद हो गई']], 0],
  ]);

  // ================================================================ NEW: The Monkey King's Bridge (Jataka)
  LONG('monkeyking', ['The Monkey King’s Bridge', 'वानरराज का पुल'], '🐒', [
    ['river', '@🐒 🥭 🌳', `Long ago, eighty thousand monkeys lived in a giant mango tree by the river Ganga. Their wise king was big and strong.`, `बहुत पहले गंगा किनारे एक विशाल आम के पेड़ पर अस्सी हज़ार बंदर रहते थे। उनका समझदार राजा बड़ा और ताकतवर था।`],
    ['river', '🐒 💡 🥭', `The king said, “Pick every mango on the branch over the river. If one falls in, people will come looking for this tree.”`, `राजा ने कहा, “नदी के ऊपर वाली डाली का हर आम तोड़ लो। अगर एक भी गिरा, तो लोग यह पेड़ ढूँढते आएँगे।”`],
    ['river', '~🥭 🤴', `But one mango was hidden by leaves. It fell into the river and floated all the way to the human king’s palace.`, `पर एक आम पत्तों में छिपा रह गया। वह नदी में गिरा और बहते-बहते इंसानों के राजा के महल तक पहुँच गया।`],
    ['palace', '🤴 😋 🥭', `The human king tasted it. “So sweet! Find that tree!” His soldiers sailed up the river and found it full of monkeys.`, `राजा ने उसे चखा। “कितना मीठा! वह पेड़ ढूँढो!” सिपाही नाव से ऊपर गए और उन्हें बंदरों से भरा पेड़ मिल गया।`],
    ['night', '💂 🏹 🌳', `At night, the soldiers surrounded the tree. “In the morning we will catch them all!” The monkeys shook with fear.`, `रात को सिपाहियों ने पेड़ घेर लिया। “सुबह सबको पकड़ लेंगे!” बंदर डर से काँपने लगे।`],
    ['night', '🐒 💪 🎋', `The monkey king did not run. He leapt across the river, tied a long bamboo cane to a tree, and jumped back holding the other end.`, `वानरराज भागे नहीं। वे छलाँग लगाकर नदी पार गए, एक लंबा बाँस एक पेड़ से बाँधा, और दूसरा सिरा पकड़कर वापस कूदे।`],
    ['night', '^🐒 🎋 🌊', `But the cane was too short! So he held the branch with his hands and the cane with his feet. His own body became the bridge.`, `पर बाँस छोटा था! तो उन्होंने हाथों से डाली पकड़ी और पैरों से बाँस। उनका अपना शरीर ही पुल बन गया।`],
    ['night', '🐒 🐒 🐒 ^🐒', `“Run across me, quickly!” One by one, all eighty thousand monkeys ran over their king’s back to safety.`, `“मेरे ऊपर से जल्दी भागो!” एक-एक करके सारे अस्सी हज़ार बंदर अपने राजा की पीठ पर से सुरक्षित पार हो गए।`],
    ['river', '🤴 😮 🐒', `In the morning the human king saw the tired, brave monkey king. He was amazed. “You risked yourself to save everyone?”`, `सुबह इंसानों के राजा ने थके, बहादुर वानरराज को देखा। वह हैरान रह गया। “तुमने सबको बचाने के लिए खुद को खतरे में डाला?”`],
    ['palace', '🤴 🙏 🐒', `“A true king cares for his people more than himself,” said the monkey king. The human king bowed and promised to rule the same way.`, `“सच्चा राजा अपनी प्रजा की खुद से ज़्यादा परवाह करता है,” वानरराज ने कहा। राजा ने सिर झुकाया और वैसे ही राज करने का वचन दिया।`],
  ], ['A true leader takes care of others first.', 'सच्चा नेता पहले दूसरों का ध्यान रखता है।'], [
    [['Where did the monkeys live?', 'बंदर कहाँ रहते थे?'], [['In a giant mango tree', 'विशाल आम के पेड़ पर'], ['In a cave', 'गुफा में'], ['In a palace', 'महल में']], 0],
    [['How did the human king find the tree?', 'राजा को पेड़ का पता कैसे चला?'], [['A mango floated down the river', 'एक आम नदी में बहकर आया'], ['A bird told him', 'चिड़िया ने बताया'], ['He saw it in a dream', 'उसने सपने में देखा']], 0],
    [['What did the monkey king make with his body?', 'वानरराज ने अपने शरीर से क्या बनाया?'], [['A bridge', 'पुल'], ['A boat', 'नाव'], ['A wall', 'दीवार']], 0],
    [['What makes a true leader?', 'सच्चा नेता कौन है?'], [['One who cares for others first', 'जो पहले दूसरों का ध्यान रखे'], ['One who eats most mangoes', 'जो सबसे ज़्यादा आम खाए'], ['One who shouts', 'जो चिल्लाए']], 0],
  ], [2, 3]);

  // ================================================================ NEW: The Brahmin and the Goat (Panchatantra)
  LONG('goat', ['Panchatantra: The Brahmin and the Goat', 'पंचतंत्र: ब्राह्मण और बकरी'], '🐐', [
    ['market', '👴 🐐', `A kind priest named Mitra Sharma was given a fat, healthy goat as a gift. He carried it home on his shoulders.`, `मित्र शर्मा नाम के एक भले पुजारी को दान में एक मोटी-ताज़ी बकरी मिली। वह उसे कंधे पर उठाकर घर ले चले।`],
    ['road', '🦹 🦹 🦹 😈', `Three tricksters saw him. “Let’s fool him and take the goat,” they whispered. They hid at three places along the road.`, `तीन ठगों ने उन्हें देखा। “चलो इसे बेवकूफ़ बनाकर बकरी ले लें,” वे फुसफुसाए। वे रास्ते में तीन जगह छिप गए।`],
    ['road', '🦹 😮 👴 🐐', `The first trickster stepped out. “Sir! Why is a holy man like you carrying a dirty dog?”`, `पहला ठग सामने आया। “महाराज! आप जैसे पुजारी गंदा कुत्ता क्यों उठाए हुए हैं?”`],
    ['road', '👴 😠 🐐', `“This is a goat, not a dog!” said the priest crossly, and walked on.`, `“यह बकरी है, कुत्ता नहीं!” पुजारी ने नाराज़ होकर कहा, और आगे बढ़ गए।`],
    ['road', '🦹 🤔 👴', `A little later, the second trickster said, “Sir, why are you carrying a dead calf? That is strange!”`, `थोड़ी दूर पर दूसरा ठग बोला, “महाराज, आप मरा हुआ बछड़ा क्यों उठाए हैं? अजीब बात है!”`],
    ['road', '👴 😟 🐐', `The priest looked at the goat. “Is it really a goat?” He began to feel unsure.`, `पुजारी ने बकरी को देखा। “क्या यह सच में बकरी है?” उन्हें शक होने लगा।`],
    ['road', '🦹 😱 👴', `Then the third trickster jumped back in fright. “A donkey on your shoulders?! Put it down at once!”`, `फिर तीसरा ठग डरकर पीछे कूदा। “आपके कंधों पर गधा?! तुरंत नीचे रखिए!”`],
    ['road', '👴 😵 🐐', `“Three people cannot all be wrong,” thought the priest. “This must be a magic animal!” He dropped the goat and ran home.`, `“तीन लोग गलत नहीं हो सकते,” पुजारी ने सोचा। “यह कोई जादुई जानवर होगा!” उन्होंने बकरी छोड़ी और घर भाग गए।`],
    ['road', '🦹 🐐 🦹', `The tricksters laughed and took the goat. The priest had believed others instead of his own eyes.`, `ठग हँसे और बकरी ले गए। पुजारी ने अपनी आँखों की जगह दूसरों की बात मान ली थी।`],
  ], ['Trust what you know is true. Do not let others fool you, even if many say the same thing.', 'जो तुम सच जानते हो, उस पर भरोसा रखो। बहुत लोग एक ही बात कहें, तब भी किसी के बहकावे में मत आओ।'], [
    [['What was the priest carrying?', 'पुजारी क्या उठाए हुए थे?'], [['A goat', 'बकरी'], ['A dog', 'कुत्ता'], ['A donkey', 'गधा']], 0],
    [['How many tricksters were there?', 'कितने ठग थे?'], [['Three', 'तीन'], ['One', 'एक'], ['Ten', 'दस']], 0],
    [['Why did the priest drop the goat?', 'पुजारी ने बकरी क्यों छोड़ी?'], [['He believed the tricksters', 'उन्होंने ठगों की बात मान ली'], ['It was heavy', 'वह भारी थी'], ['It bit him', 'उसने काटा']], 0],
    [['What should he have done?', 'उन्हें क्या करना चाहिए था?'], [['Trust his own eyes', 'अपनी आँखों पर भरोसा'], ['Run faster', 'तेज़ भागना'], ['Buy a dog', 'कुत्ता खरीदना']], 0],
  ], [2, 3]);

  // ================================================================ NEW: Birbal and the Mango Tree (planting for others)
  LONG('mangotree', ['Akbar, Birbal and the Old Gardener', 'अकबर, बीरबल और बूढ़ा माली'], '🥭', [
    ['road', '🤴 🐎 🧔', `Emperor Akbar and Birbal were riding through the countryside one morning.`, `एक सुबह बादशाह अकबर और बीरबल घोड़ों पर गाँव की ओर घूमने निकले।`],
    ['field', '👴 🌱 🪏', `They saw a very old man digging the soil and planting a tiny mango seedling.`, `उन्होंने देखा कि एक बहुत बूढ़ा आदमी मिट्टी खोदकर आम का नन्हा पौधा लगा रहा है।`],
    ['field', '🤴 🤔 👴', `Akbar asked, “Old man, a mango tree takes many years to give fruit. You may not be here to eat them. Why plant it?”`, `अकबर ने पूछा, “बाबा, आम का पेड़ फल देने में कई साल लेता है। शायद आप उसके फल न खा पाएँ। फिर क्यों लगा रहे हैं?”`],
    ['field', '👴 😊 🥭', `The old man smiled. “Huzoor, I have eaten mangoes all my life from trees that others planted before me.”`, `बूढ़ा मुस्कुराया। “हुज़ूर, मैंने जीवन भर उन पेड़ों के आम खाए जो मुझसे पहले दूसरों ने लगाए थे।”`],
    ['field', '👴 🌱 🧒', `“Now I plant this tree so that children and grandchildren after me can eat sweet mangoes and sit in its shade.”`, `“अब मैं यह पेड़ लगा रहा हूँ ताकि मेरे बाद बच्चे और पोते-पोतियाँ मीठे आम खाएँ और इसकी छाँव में बैठें।”`],
    ['field', '🤴 😮 🧔', `Akbar was touched. Birbal said, “Your Majesty, this is true wisdom – thinking of others, even those we will never meet.”`, `अकबर का दिल भर आया। बीरबल बोले, “जहाँपनाह, यही असली समझदारी है – दूसरों के बारे में सोचना, उनके भी जिनसे हम कभी नहीं मिलेंगे।”`],
    ['field', '🤴 🎁 👴', `Akbar gave the old man a bag of gold coins. The old man laughed, “See! My tree has given fruit already!”`, `अकबर ने बूढ़े को सोने के सिक्कों की थैली दी। बूढ़ा हँसा, “देखिए! मेरे पेड़ ने तो अभी से फल दे दिया!”`],
    ['tree', '🧒 🥭 👧 🌳', `Years later, the tree grew big and full of mangoes. Children climbed it, ate its fruit, and played in its cool shade.`, `सालों बाद पेड़ बड़ा हुआ और आमों से लद गया। बच्चे उस पर चढ़ते, फल खाते और उसकी ठंडी छाँव में खेलते।`],
  ], ['Do good things for the future. Plant trees for those who come after us.', 'आने वाले कल के लिए अच्छे काम करो। अपने बाद आने वालों के लिए पेड़ लगाओ।'], [
    [['What was the old man planting?', 'बूढ़ा क्या लगा रहा था?'], [['A mango tree', 'आम का पेड़'], ['Flowers', 'फूल'], ['Wheat', 'गेहूँ']], 0],
    [['Who would eat its fruit?', 'उसके फल कौन खाएगा?'], [['Children in the future', 'आने वाले बच्चे'], ['Only the old man', 'बस बूढ़ा'], ['The horse', 'घोड़ा']], 0],
    [['What can YOU plant this year?', 'इस साल तुम क्या लगा सकते हो?'], [['A tree or a plant', 'एक पेड़ या पौधा'], ['A plastic bag', 'प्लास्टिक की थैली'], ['Nothing', 'कुछ नहीं']], 0],
  ]);

  // ================================================================ NEW: The Golden Swan (Jataka)
  LONG('goldenswan', ['The Golden Swan', 'सुनहरा हंस'], '🦢', [
    ['village', '👩 👧 👧 🛖', `A poor mother lived with her two daughters in a small hut. They often went to bed hungry.`, `एक गरीब माँ अपनी दो बेटियों के साथ छोटी सी झोपड़ी में रहती थी। वे अक्सर भूखे सो जाते।`],
    ['lake', '~🦢 ✨', `In a lake nearby lived a swan with shining golden feathers. He saw how poor the family was and felt sorry for them.`, `पास की झील में सुनहरे चमकते पंखों वाला एक हंस रहता था। उसने देखा कि परिवार कितना गरीब है और उसे दया आई।`],
    ['village', '^🦢 👩 👧', `One day he flew to their hut. “Every few days, I will give you one golden feather. Sell it and buy what you need.”`, `एक दिन वह उड़कर उनकी झोपड़ी पर आया। “हर कुछ दिनों में मैं तुम्हें एक सुनहरा पंख दूँगा। उसे बेचकर ज़रूरत की चीज़ें ले लेना।”`],
    ['market', '👩 🪶 🍚', `The family sold the feathers and bought food, clothes and a warm blanket. They were happy and thankful.`, `परिवार ने पंख बेचकर खाना, कपड़े और गरम कंबल खरीदे। वे खुश और आभारी थे।`],
    ['home', '👩 😈 💭', `But slowly the mother became greedy. “Why wait for one feather? If I take ALL his feathers, we will be rich at once!”`, `पर धीरे-धीरे माँ लालची हो गई। “एक पंख का इंतज़ार क्यों? अगर सारे पंख ले लूँ, तो हम एक बार में अमीर हो जाएँगे!”`],
    ['home', '👧 🙅 👩', `Her daughters said, “No, mother! He is our friend. It will hurt him!” But she did not listen.`, `बेटियों ने कहा, “नहीं माँ! वह हमारा दोस्त है। उसे दुख होगा!” पर उसने नहीं सुना।`],
    ['home', '👩 🪶 😮', `When the swan came, she grabbed him and pulled out all his feathers. But they turned plain white in her hands! Golden feathers only stay golden when given with love.`, `जब हंस आया, उसने उसे पकड़कर सारे पंख नोच लिए। पर उसके हाथ में वे सादे सफ़ेद हो गए! सुनहरे पंख तभी सुनहरे रहते हैं जब प्यार से दिए जाएँ।`],
    ['home', '👩 😢 🦢', `The mother cried with shame. “I am so sorry. I was greedy.” She looked after the swan until his feathers grew back.`, `माँ शर्म से रो पड़ी। “मुझे माफ़ करो। मैं लालची हो गई थी।” उसने पंख वापस उगने तक हंस की देखभाल की।`],
    ['lake', '^🦢 👧 👧', `His new feathers were white, and he flew away to his lake. The family learned to work hard and be content.`, `उसके नए पंख सफ़ेद थे, और वह अपनी झील पर उड़ गया। परिवार ने मेहनत करना और संतोष रखना सीखा।`],
  ], ['Be thankful for what you are given. Greed spoils everything.', 'जो मिला है उसके लिए आभारी रहो। लालच सब कुछ बिगाड़ देता है।'], [
    [['What was special about the swan?', 'हंस में क्या खास था?'], [['Golden feathers', 'सुनहरे पंख'], ['He could talk Hindi only', 'वह सिर्फ़ हिंदी बोलता था'], ['He was huge', 'वह बहुत बड़ा था']], 0],
    [['What did the mother do wrong?', 'माँ ने क्या गलत किया?'], [['Took all the feathers out of greed', 'लालच में सारे पंख नोच लिए'], ['Bought food', 'खाना खरीदा'], ['Thanked the swan', 'हंस को धन्यवाद दिया']], 0],
    [['What happened to the feathers?', 'पंखों का क्या हुआ?'], [['They turned white', 'वे सफ़ेद हो गए'], ['They grew bigger', 'बड़े हो गए'], ['They flew away', 'उड़ गए']], 0],
  ]);
})();
